import React, { useEffect, useState, useMemo, useRef, useCallback } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useIntl } from 'react-intl';
import { getActivityFeed } from 'Screens/Contextualization/Dashboard/actions/Actions';
import { selectActiveFeeds, selectIsLoadingState, selectActivityFeedShowMore } from 'store/Dashboard/selectors';
import { selectCurrentWorkspace } from 'store/Faraday/selectors';
import { DASHBOARD_FILTERS } from 'store/Filters/constants';
import { setFilter } from 'store/Filters/actions';
import { redirect } from 'store/Router/actions';
import DateFormatter from 'Common/Components/DateFormatter';
import SpinnerComponent from 'Common/Components/SpinnerContainer';
import formatNumber from 'Common/Functions/FormatNumber';
import {
  Wrapper,
  ActivityIcon,
  Empty,
  ContentWrapper,
  WrapperActivity,
  ActivityDescription,
  ActivityFooter,
  Author,
  Vulnerabilities,
  HostsAndServices,
  Time,
  Tag,
  Tool,
  Dark,
  Light,
  VulnerabilitiesQuantity,
  VulnerabilitiesText,
  ToolText,
  DotsLoader,
  Dot
} from './styled';
import { Divider } from '@material-ui/core';
import TitleWrapper from '../components/TitleWrapper';

const ActivityFeedWidget = () => {
  const dispatch = useDispatch();
  const data = useSelector(selectActiveFeeds);
  const hasMore = useSelector(selectActivityFeedShowMore);
  const workspaceSelected = useSelector(selectCurrentWorkspace);
  const isFetching = useSelector((state) => selectIsLoadingState(state, 'activityFeed'));

  const [page, setPage] = useState(1);
  const sentinelRef = useRef(null);

  const intl = useIntl();
  const translations = useMemo(() => ({
    title: intl.formatMessage({ id: 'dashboard.widgets.activityFeed.title' }),
    empty: intl.formatMessage({ id: 'dashboard.widgets.activityFeed.empty' }),
    vulnerabilities: intl.formatMessage({ id: 'dashboard.widgets.activityFeed.vulnerabilities' }),
    assets: intl.formatMessage({ id: 'dashboard.widgets.activityFeed.assets' }),
    noAssets: intl.formatMessage({ id: 'dashboard.widgets.activityFeed.noAssets' }),
    services: intl.formatMessage({ id: 'dashboard.widgets.activityFeed.services' }),
    noServices: intl.formatMessage({ id: 'dashboard.widgets.activityFeed.noServices' }),
    triggeredBy: intl.formatMessage({ id: 'dashboard.widgets.activityFeed.triggeredBy' }),
    imported: intl.formatMessage({ id: 'dashboard.widgets.activityFeed.imported' })
  }), [intl]);

  useEffect(() => {
    dispatch(getActivityFeed(page));
  }, [dispatch, page, workspaceSelected]);

  const loadMore = useCallback(() => {
    if (!isFetching && hasMore) setPage((p) => p + 1);
  }, [isFetching, hasMore]);

  useEffect(() => {
    const sentinel = sentinelRef.current;
    if (!sentinel) return;
    const observer = new IntersectionObserver(
      ([entry]) => { if (entry.isIntersecting) loadMore(); },
      { threshold: 0.5 }
    );
    observer.observe(sentinel);
    return () => observer.disconnect();
  }, [loadMore]);

  const onClick = (command) => {
    dispatch(setFilter('vulns', DASHBOARD_FILTERS.commandIdFilter(command.toString())));
    dispatch(redirect(`/manage/${workspaceSelected}`));
  };

  if (isFetching && page === 1) return <SpinnerComponent height="250px" />;

  const header = (
    <TitleWrapper
      title={ translations.title }
      icon={ <ActivityIcon /> }
    />
  );

  if (!data?.activities?.length) {
    return (
      <Wrapper>
        {header}
        <Empty>{translations.empty}</Empty>
      </Wrapper>
    );
  }

  const elements = data.activities.filter(
    (x) => x.hosts_count > 0 || x.services_count > 0 || x.vulnerabilities_count > 0
  );

  return (
    <Wrapper>
      {header}
      <Divider style={ { margin: '16px 0' } } />
      <ContentWrapper>
        {elements.map((activity, index) => {
          const isAgent = activity.import_source === 'agent';
          const isReport = activity.import_source === 'report';
          let author = activity.creator;
          let fileName = activity.params;

          if (isAgent) {
            author = activity.command;
          } else if (isReport) {
            author = activity.creator;
            const paramIndex = activity.params.indexOf('_');
            fileName = activity.params.slice(paramIndex + 1);
          }

          return (
            <WrapperActivity
              onClick={ () => onClick(activity._id) }
              key={ `dashboard_activity_feed_${index}` }
            >
              <ActivityDescription>
                <Vulnerabilities>
                  <VulnerabilitiesQuantity>
                    {formatNumber(activity.vulnerabilities_count)}
                  </VulnerabilitiesQuantity>
                  <VulnerabilitiesText>{translations.vulnerabilities}</VulnerabilitiesText>
                </Vulnerabilities>
                <HostsAndServices>
                  {activity.hosts_count
                    ? `${formatNumber(activity.hosts_count)} ${translations.assets}`
                    : translations.noAssets}
                  {activity.services_count
                    ? ` ${formatNumber(activity.services_count)} ${translations.services}`
                    : ` ${translations.noServices}`}
                </HostsAndServices>
              </ActivityDescription>
              {isAgent && (
                <Author>
                  <Light>{translations.triggeredBy} </Light>
                  <Dark>{author}</Dark>
                </Author>
              )}
              {isReport && (
                <Author>
                  <Dark>{author}</Dark>
                  <Light> {translations.imported} </Light>
                  <Dark>{fileName}</Dark>
                </Author>
              )}
              <ActivityFooter>
                <Tool>
                  <ToolText>
                    {activity.tool}
                  </ToolText>
                </Tool>
                <Tag>
                  <Time>
                    <DateFormatter date={ activity.date } />
                  </Time>
                </Tag>
              </ActivityFooter>
            </WrapperActivity>
          );
        })}
        {hasMore && <div ref={ sentinelRef } style={ { height: '1px' } } />}
        {isFetching && page > 1 && (
          <DotsLoader>
            <Dot delay="0s" />
            <Dot delay="0.2s" />
            <Dot delay="0.4s" />
          </DotsLoader>
        )}
      </ContentWrapper>
    </Wrapper>
  );
};

export default ActivityFeedWidget;
